'use strict'

// The generated loader tries two sources for every platform: the binary this
// package ships, then a sibling package holding that one platform. The release
// bundles every platform's binary into this package and publishes nothing else,
// so the sibling branches can never resolve - they only add a failed require to
// the error chain when a load goes wrong. Dropping them leaves the loader
// reaching for the files it actually ships, and leaves `yggdryl` the only
// package name this package imports.
//
// The loader is regenerated by `napi build`, so this runs after every build.
// It is deliberately strict: an unrecognized shape is an error rather than a
// silent no-op, because a silent no-op would republish the sibling requires.

const { readFileSync, writeFileSync } = require('node:fs')
const { join } = require('node:path')

const check = process.argv.includes('--check')
const root = join(__dirname, '..')
const loaderPath = join(root, 'index.js')
const packageName = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8')).name

const escaped = packageName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
// A sibling binding package: the package name plus a platform suffix. The
// shipped binaries are required by relative path, so they never match.
const siblingRequire = new RegExp(String.raw`require\('${escaped}-[^']+'\)`, 'g')

function stripNativeSiblings(source) {
  // The per-platform fallback the generator emits after each shipped-binary
  // attempt, at whatever indentation the platform branch sits on.
  const block = new RegExp(
    [
      String.raw`[ \t]*try \{\n`,
      String.raw`[ \t]*const binding = require\('${escaped}-[^']+'\)\n`,
      String.raw`[ \t]*const bindingPackageVersion = require\('${escaped}-[^']+/package\.json'\)\.version\n`,
      String.raw`[ \t]*if \(bindingPackageVersion !== [^\n]*\n`,
      String.raw`[ \t]*throw new Error\([^\n]*\n`,
      String.raw`[ \t]*\}\n`,
      String.raw`[ \t]*return binding\n`,
      String.raw`[ \t]*\} catch \(e\) \{\n`,
      String.raw`[ \t]*loadErrors\.push\(e\)\n`,
      String.raw`[ \t]*\}\n`,
    ].join(''),
    'g',
  )
  return source.replace(block, '')
}

// Removes the `if (...) { ... }` statement starting on `startLine`, matching
// braces so the whole statement goes rather than a guessed line count.
function removeStatement(lines, startLine) {
  let depth = 0
  for (let line = startLine; line < lines.length; line += 1) {
    for (const character of lines[line]) {
      if (character === '{') depth += 1
      else if (character === '}') depth -= 1
    }
    if (depth === 0) {
      lines.splice(startLine, line - startLine + 1)
      return true
    }
  }
  throw new Error(`unterminated statement at index.js:${startLine + 1}`)
}

function stripWasiSibling(source) {
  const lines = source.split('\n')
  for (let line = 0; line < lines.length; line += 1) {
    if (!/^\s*if \(!wasiBindingLoaded/.test(lines[line])) continue
    // Two identical guards follow each other: the first loads the shipped
    // .wasi.cjs, the second the sibling package. Only the sibling one goes.
    const depthAtStart = lines[line].split('{').length - lines[line].split('}').length
    let depth = depthAtStart
    let end = line
    while (depth !== 0 && end + 1 < lines.length) {
      end += 1
      depth += lines[end].split('{').length - lines[end].split('}').length
    }
    const body = lines.slice(line, end + 1).join('\n')
    if (siblingRequire.test(body) || body.includes(`'${packageName}-wasm32-wasi'`)) {
      siblingRequire.lastIndex = 0
      removeStatement(lines, line)
      return lines.join('\n')
    }
    siblingRequire.lastIndex = 0
  }
  return source
}

const source = readFileSync(loaderPath, 'utf8')
const stripped = stripWasiSibling(stripNativeSiblings(source))

// The whole point of the step: no sibling package may survive it.
const survivors = stripped.match(siblingRequire)
if (survivors) {
  throw new Error(
    `index.js still requires ${survivors.length} sibling package(s) after stripping, ` +
      `first ${survivors[0]}. The generated loader's shape changed - update this script.`,
  )
}

// A loader that resolves nothing would also have no survivors, so prove the
// shipped binaries are still reachable.
const shipped = stripped.match(/require\('\.\/[^']+\.node'\)/g)
if (!shipped || shipped.length === 0) {
  throw new Error('index.js no longer requires any shipped binary')
}

if (check) {
  if (stripped !== source) {
    throw new Error('index.js still contains sibling binding packages; run `npm run build`')
  }
  console.log(`index.js requires only its ${shipped.length} shipped binaries`)
} else if (stripped !== source) {
  writeFileSync(loaderPath, stripped)
  const removed = (source.match(siblingRequire) || []).length
  console.log(`index.js: removed ${removed} sibling package require(s)`)
} else {
  console.log('index.js: already free of sibling package requires')
}
